class Solution:
    def smallestDistancePair(self, nums: list[int], k: int) -> int:
        nums=sorted(nums)
        def count(limit):
            total=0
            for i in range(len(nums)):
                lo,hi=i+1,len(nums)
                while lo < hi:
                    mid=(lo+hi)//2
                    if nums[mid]-nums[i] <= limit: lo=mid+1
                    else: hi=mid
                total += lo-i-1
            return total
        lo,hi=0,nums[-1]-nums[0]
        while lo < hi:
            mid=(lo+hi)//2
            if count(mid) >= k: hi=mid
            else: lo=mid+1
        return lo

