        nums=sorted(nums)
        def count(limit):
            total=left=0
            for right,x in enumerate(nums):
                while x-nums[left] > limit: left += 1
                total += right-left
            return total
        lo,hi=0,nums[-1]-nums[0]
        while lo < hi:
            mid=(lo+hi)//2
            if count(mid) >= k: hi=mid
            else: lo=mid+1
        return lo

